Output2Best Case:  Constant Time irrespective of input size. This will take place if the element to be searched is on the first index of the given list. So, the number of comparisons, in this case, is 1.Average Case:  Linear Time, This will take place if the element to be searched is at the middle index (in an average search) of the given list.Worst Case: The element to be searched is not present in the list2. Special Array Sum:  In this example, we will take an array of length (n) and deals with the following cases :If (n) is even then our output will be 0If (n) is odd then our output will be the sum of the elements of the array.
            C++

    #include <iostream>
#include <vector>
using namespace std;

int getSum(const vector<int> &arr1)
{
    int n = arr1.size();
    if (n % 2 == 0) // (n) is even
        return 0;

    int sum = 0;
    for (int i = 0; i < n; i++)
    {
        sum += arr1[i];
    }
    return sum; // (n) is odd
}

int main()
{

    // Declaring two vectors, one with an odd length
    // and the other with an even length
    vector<int> arr1 = {1, 2, 3, 4};
    vector<int> arr2 = {1, 2, 3, 4, 5};
    cout << getSum(arr1) << endl;
    cout << getSum(arr2) << endl;
    return 0;
}


